  $tpl$, $tpl${"hsg":{"hero_kicker":"HOME PROTECTION","secondary_heading":"Also in this issue","local_heading":"From your local team","offer_heading":"Offer for our neighbors","footer_reason":"You are receiving this because you are a customer or subscribed to our updates."},"hospitality":{"hero_kicker":"THE TAPROOM REPORT","secondary_heading":"On tap this week","local_heading":"Around the neighborhood","offer_heading":"For our members and regulars","footer_reason":"You are receiving this because you joined our list or visited us."}}$tpl$::jsonb, true)
on conflict (template_key, version) do update set is_current = true;

