  $tpl$, $tpl${"hsg":{"hero_kicker":"THIS WEEK'S TIP","secondary_heading":"Also in this issue","local_heading":"From your local team","offer_heading":"Offer for our neighbors","footer_reason":"You are receiving this because you are a customer or subscribed to our updates."},"hospitality":{"hero_kicker":"BREWER'S NOTES","secondary_heading":"On tap this week","local_heading":"Around the neighborhood","offer_heading":"For our members and regulars","footer_reason":"You are receiving this because you joined our list or visited us."}}$tpl$::jsonb, true)
on conflict (template_key, version) do update set is_current = true;

update template_versions set is_current = false where template_key = 'seasonal_guide' and version <> 2;
insert into template_versions (template_key, version, mjml_source, compiled_html, labels, is_current)
values ('seasonal_guide', 2, $tpl$<mjml><mj-head>
    <mj-preview>[[preview_text]]</mj-preview>
    <mj-title>[[edition_subject]]</mj-title>
    <mj-attributes>
      <mj-all font-family="Arial, Helvetica, sans-serif" />
      <mj-text font-size="16px" line-height="1.55" color="#26303a" />
      <mj-section background-color="#ffffff" padding="16px 12px" />
      <mj-button font-weight="700" border-radius="4px" font-size="15px" inner-padding="12px 22px" />
    </mj-attributes>
    <mj-raw><meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark"></mj-raw>
    <mj-style>
      @media (prefers-color-scheme: dark) {
        .page-bg, .page-bg > table { background-color: #14181d !important; }
        .card, .card > table, .card td { background-color: #1f252c !important; }
        /* Only the default ink turns light, so brand-coloured labels keep their colour. */
        .card div[style*="color:#26303a"], .card div[style*="color:#2a2522"] { color: #e8ecf0 !important; }
      }
    </mj-style>
    <mj-raw><!-- page color #e9efe9 --></mj-raw>
  </mj-head><mj-body background-color="#e9efe9" width="620px" css-class="page-bg">
    <mj-section background-color="[[secondary_color]]" padding="20px 12px"><mj-column>
      <mj-raw>[[#logo_url]]</mj-raw><mj-image src="[[logo_url]]" alt="[[newsletter_name]] logo" align="center" width="160px" padding="0 12px 10px" /><mj-raw>[[/logo_url]]</mj-raw>
      <mj-text align="center" font-size="26px" font-weight="700" color="#ffffff" padding-bottom="0">[[newsletter_name]]</mj-text>
      <mj-text align="center" font-size="14px" color="#ffffff" padding-top="2px">[[hero_kicker]]</mj-text>
    </mj-column></mj-section>
    <mj-raw>[[#hero_image_url]]</mj-raw><mj-section padding="0" css-class="card"><mj-column><mj-image src="[[hero_image_url]]" alt="[[hero_image_alt]]" padding="0" fluid-on-mobile="true" /></mj-column></mj-section><mj-raw>[[/hero_image_url]]</mj-raw>
    <mj-section css-class="card"><mj-column>
      <mj-text font-size="25px" font-weight="700" line-height="1.25" padding-bottom="6px">[[hero_headline]]</mj-text>
      <mj-text padding-top="0">[[hero_body_html]]</mj-text>
      <mj-raw>[[#hero_cta_label]]</mj-raw><mj-button href="[[hero_cta_url]]" background-color="[[primary_color]]" color="#ffffff" align="left">[[hero_cta_label]]</mj-button><mj-raw>[[/hero_cta_label]]</mj-raw>
    </mj-column></mj-section>
    <mj-section padding="6px 12px 0" css-class="card"><mj-column><mj-text font-size="18px" font-weight="700" color="[[secondary_color]]">[[secondary_heading]]</mj-text></mj-column></mj-section>
    <mj-raw>[[#secondary]]</mj-raw><mj-section padding="4px 12px 10px" css-class="card">
      <mj-raw>[[#image_url]]</mj-raw><mj-column width="35%"><mj-image src="[[image_url]]" alt="[[image_alt]]" padding="6px 12px" /></mj-column><mj-raw>[[/image_url]]</mj-raw>
      <mj-column>
        <mj-text font-size="17px" font-weight="700" padding-bottom="4px">[[headline]]</mj-text>
        <mj-text padding-top="0">[[teaser]]</mj-text>
