values ('improvement_savings', 2, $tpl$<mjml><mj-head>
    <mj-preview>[[preview_text]]</mj-preview>
    <mj-title>[[edition_subject]]</mj-title>
    <mj-attributes>
      <mj-all font-family="Arial, Helvetica, sans-serif" />
      <mj-text font-size="16px" line-height="1.55" color="#26303a" />
      <mj-section background-color="#ffffff" padding="16px 12px" />
      <mj-button font-weight="700" border-radius="4px" font-size="15px" inner-padding="12px 22px" />
    </mj-attributes>
    <mj-raw><meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark"></mj-raw>
    <mj-style>
      @media (prefers-color-scheme: dark) {
        .page-bg, .page-bg > table { background-color: #14181d !important; }
        .card, .card > table, .card td { background-color: #1f252c !important; }
        /* Only the default ink turns light, so brand-coloured labels keep their colour. */
        .card div[style*="color:#26303a"], .card div[style*="color:#2a2522"] { color: #e8ecf0 !important; }
      }
    </mj-style>
    <mj-raw><!-- page color #edf0f7 --></mj-raw>
  </mj-head><mj-body background-color="#edf0f7" width="620px" css-class="page-bg">
    <mj-section padding="18px 12px" css-class="card">
      <mj-column width="55%"><mj-raw>[[#logo_url]]</mj-raw><mj-image src="[[logo_url]]" alt="[[newsletter_name]] logo" align="left" width="150px" padding="0 12px 10px" /><mj-raw>[[/logo_url]]</mj-raw><mj-text font-size="21px" font-weight="700" color="[[primary_color]]" padding-bottom="0">[[newsletter_name]]</mj-text></mj-column>
      <mj-column width="45%"><mj-text align="right" font-size="13px" color="[[secondary_color]]" font-weight="700">[[hero_kicker]]</mj-text></mj-column>
    </mj-section>
    <mj-raw>[[#hero_image_url]]</mj-raw><mj-section padding="0" css-class="card"><mj-column><mj-image src="[[hero_image_url]]" alt="[[hero_image_alt]]" padding="0" fluid-on-mobile="true" /></mj-column></mj-section><mj-raw>[[/hero_image_url]]</mj-raw>
    <mj-section css-class="card"><mj-column>
      <mj-text font-size="24px" font-weight="700" line-height="1.25" padding-bottom="6px">[[hero_headline]]</mj-text>
      <mj-text padding-top="0">[[hero_body_html]]</mj-text>
      <mj-raw>[[#hero_cta_label]]</mj-raw><mj-button href="[[hero_cta_url]]" background-color="[[secondary_color]]" color="#ffffff" align="left">[[hero_cta_label]]</mj-button><mj-raw>[[/hero_cta_label]]</mj-raw>
    </mj-column></mj-section>
    <mj-raw>[[#offer_headline]]</mj-raw><mj-section background-color="[[secondary_color]]" padding="22px 12px"><mj-column>
    <mj-text font-size="13px" font-weight="700" color="#ffffff" padding-bottom="2px">[[offer_heading]]</mj-text>
    <mj-text font-size="21px" font-weight="700" line-height="1.25" color="#ffffff" padding-top="0" padding-bottom="4px">[[offer_headline]]</mj-text>
    <mj-text color="#ffffff" padding-top="0">[[offer_body]]</mj-text>
    <mj-raw>[[#offer_cta_label]]</mj-raw><mj-button href="[[offer_url]]" background-color="#ffffff" color="[[secondary_color]]" align="left">[[offer_cta_label]]</mj-button><mj-raw>[[/offer_cta_label]]</mj-raw>
  </mj-column></mj-section><mj-raw>[[/offer_headline]]</mj-raw>
    <mj-section padding="10px 12px 0" css-class="card"><mj-column><mj-text font-size="18px" font-weight="700" color="[[primary_color]]">[[secondary_heading]]</mj-text></mj-column></mj-section>
    <mj-raw>[[#secondary]]</mj-raw><mj-section padding="0 12px 10px" css-class="card"><mj-column>
      <mj-text font-size="17px" font-weight="700" padding-bottom="4px">[[headline]]</mj-text>
      <mj-text padding-top="0">[[teaser]]</mj-text>
      <mj-raw>[[#cta_label]]</mj-raw><mj-text padding-top="0"><a href="[[cta_url]]" style="color:[[primary_color]];font-weight:700;">[[cta_label]] &rarr;</a></mj-text><mj-raw>[[/cta_label]]</mj-raw>
      <mj-divider border-width="1px" border-color="#dfe4ea" padding="4px 12px 0" />
    </mj-column></mj-section><mj-raw>[[/secondary]]</mj-raw>
    <mj-raw>[[#local_note]]</mj-raw><mj-section background-color="#f4f6f8" css-class="card"><mj-column><mj-text font-size="13px" font-weight="700" color="[[primary_color]]" padding-bottom="2px">[[local_heading]]</mj-text><mj-text padding-top="0">[[local_note]]</mj-text></mj-column></mj-section><mj-raw>[[/local_note]]</mj-raw>
    <mj-section background-color="#26303a" padding="22px 12px"><mj-column>
