  $tpl$, $tpl${"hsg":{"hero_kicker":"IMPROVE & SAVE","secondary_heading":"Also in this issue","local_heading":"From your local team","offer_heading":"Offer for our neighbors","footer_reason":"You are receiving this because you are a customer or subscribed to our updates."},"hospitality":{"hero_kicker":"EVENTS & MEMBER VALUE","secondary_heading":"On tap this week","local_heading":"Around the neighborhood","offer_heading":"For our members and regulars","footer_reason":"You are receiving this because you joined our list or visited us."}}$tpl$::jsonb, true)
on conflict (template_key, version) do update set is_current = true;

update template_versions set is_current = false where template_key = 'premium_magazine' and version <> 2;
insert into template_versions (template_key, version, mjml_source, compiled_html, labels, is_current)
values ('premium_magazine', 2, $tpl$<mjml><mj-head>
    <mj-preview>[[preview_text]]</mj-preview>
    <mj-title>[[edition_subject]]</mj-title>
    <mj-attributes>
      <mj-all font-family="Georgia, 'Times New Roman', serif" />
      <mj-text font-size="16px" line-height="1.55" color="#2a2522" />
      <mj-section background-color="#ffffff" padding="16px 12px" />
      <mj-button font-weight="700" border-radius="4px" font-size="15px" inner-padding="12px 22px" />
    </mj-attributes>
    <mj-raw><meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark"></mj-raw>
    <mj-style>
      @media (prefers-color-scheme: dark) {
        .page-bg, .page-bg > table { background-color: #14181d !important; }
        .card, .card > table, .card td { background-color: #1f252c !important; }
        /* Only the default ink turns light, so brand-coloured labels keep their colour. */
        .card div[style*="color:#26303a"], .card div[style*="color:#2a2522"] { color: #e8ecf0 !important; }
      }
    </mj-style>
    <mj-raw><!-- page color #f3efe8 --></mj-raw>
  </mj-head><mj-body background-color="#f3efe8" width="620px" css-class="page-bg">
    <mj-section padding="30px 12px 18px" css-class="card"><mj-column>
      <mj-raw>[[#logo_url]]</mj-raw><mj-image src="[[logo_url]]" alt="[[newsletter_name]] logo" align="center" width="140px" padding="0 12px 10px" /><mj-raw>[[/logo_url]]</mj-raw>
      <mj-text align="center" font-size="32px" line-height="1.15" color="[[primary_color]]" padding-bottom="4px">[[newsletter_name]]</mj-text>
      <mj-divider border-width="1px" border-color="[[secondary_color]]" width="70px" padding="6px 0" />
      <mj-text align="center" font-size="13px" letter-spacing="2px" color="[[secondary_color]]" padding-top="4px">[[hero_kicker]]</mj-text>
    </mj-column></mj-section>
    <mj-raw>[[#hero_image_url]]</mj-raw><mj-section padding="0" css-class="card"><mj-column><mj-image src="[[hero_image_url]]" alt="[[hero_image_alt]]" padding="0" fluid-on-mobile="true" /></mj-column></mj-section><mj-raw>[[/hero_image_url]]</mj-raw>
    <mj-section padding="22px 22px 12px" css-class="card"><mj-column>
      <mj-text font-size="30px" line-height="1.2" padding-bottom="8px">[[hero_headline]]</mj-text>
      <mj-text font-size="17px" padding-top="0" line-height="1.65">[[hero_body_html]]</mj-text>
      <mj-raw>[[#hero_cta_label]]</mj-raw><mj-button href="[[hero_cta_url]]" background-color="[[primary_color]]" color="#ffffff" align="left">[[hero_cta_label]]</mj-button><mj-raw>[[/hero_cta_label]]</mj-raw>
    </mj-column></mj-section>
    <mj-section padding="10px 22px 0" css-class="card"><mj-column><mj-divider border-width="1px" border-color="#d9d2c6" padding="0 12px" /><mj-text align="center" font-size="13px" letter-spacing="2px" color="[[secondary_color]]">[[secondary_heading]]</mj-text></mj-column></mj-section>
    <mj-raw>[[#secondary]]</mj-raw><mj-section padding="4px 22px 10px" css-class="card"><mj-column>
      <mj-text font-size="21px" line-height="1.3" padding-bottom="4px">[[headline]]</mj-text>
      <mj-text padding-top="0">[[teaser]]</mj-text>
      <mj-raw>[[#cta_label]]</mj-raw><mj-text padding-top="0"><a href="[[cta_url]]" style="color:[[primary_color]];font-weight:700;">[[cta_label]] &rarr;</a></mj-text><mj-raw>[[/cta_label]]</mj-raw>
    </mj-column></mj-section><mj-raw>[[/secondary]]</mj-raw>
    <mj-raw>[[#local_note]]</mj-raw><mj-section background-color="#faf7f1" css-class="card"><mj-column><mj-text font-size="13px" font-weight="700" color="[[primary_color]]" padding-bottom="2px">[[local_heading]]</mj-text><mj-text padding-top="0">[[local_note]]</mj-text></mj-column></mj-section><mj-raw>[[/local_note]]</mj-raw>
    <mj-raw>[[#offer_headline]]</mj-raw><mj-section background-color="[[primary_color]]" padding="22px 12px"><mj-column>
    <mj-text font-size="13px" font-weight="700" color="#ffffff" padding-bottom="2px">[[offer_heading]]</mj-text>
    <mj-text font-size="21px" font-weight="700" line-height="1.25" color="#ffffff" padding-top="0" padding-bottom="4px">[[offer_headline]]</mj-text>
    <mj-text color="#ffffff" padding-top="0">[[offer_body]]</mj-text>
    <mj-raw>[[#offer_cta_label]]</mj-raw><mj-button href="[[offer_url]]" background-color="#ffffff" color="[[primary_color]]" align="left">[[offer_cta_label]]</mj-button><mj-raw>[[/offer_cta_label]]</mj-raw>
  </mj-column></mj-section><mj-raw>[[/offer_headline]]</mj-raw>
    <mj-section background-color="#2a2522" padding="22px 12px"><mj-column>
    <mj-text font-size="13px" color="#e6dfd3" line-height="1.6">
      <span data-slot="legal"><strong>[[legal_business_name]]</strong><br>[[postal_address]]</span><br>
      [[#phone]]<a href="[[phone_url]]" style="color:#e6dfd3;">[[phone]]</a><br>[[/phone]]
      [[#website]]<a href="[[website]]" style="color:#e6dfd3;">[[website]]</a><br>[[/website]]
      [[#social]]<a href="[[social_url]]" style="color:#e6dfd3;text-transform:capitalize;">[[social_name]]</a>&nbsp;&nbsp;[[/social]]
    </mj-text>
    <mj-text font-size="12px" color="#e6dfd3" padding-top="0">[[footer_reason]] [[unsubscribe_html]]</mj-text>
  </mj-column></mj-section></mj-body></mjml>$tpl$, $tpl$<!doctype html>
